use lg_core::AccountId;
use lg_parse::{parse_statement, StatementOptions};

#[test]
fn disc_l05() {
    let text = "data;descricao;valor\n05/03/2024;\"LOJA \"\"CENTRAL\"\" LTDA\";-10,00\n06/03/2024;\"\"\"ABC\"\"\";-1,00\n";
    let opts = StatementOptions::new(AccountId::parse("ativo:banco").unwrap());
    let txns = parse_statement(text, &opts).unwrap();
    assert_eq!(txns[0].description, "LOJA \"CENTRAL\" LTDA");
    assert_eq!(txns[1].description, "\"ABC\"");
}
